const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');
  if (!payload.tenant_id) throw new Error('No tenant_id');
  const body = $input.first().json.body || {};
  const projectId = (body.project_id || '').trim();
  const tipoTramite = (body.tipo_tramite || '').trim();
  if (!projectId) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'project_id requerido' } }];
  const validTramites = ['licencia_obra_menor','licencia_obra_mayor','comunicacion_previa','declaracion_responsable','iee','cambio_uso','primera_ocupacion'];
  if (!tipoTramite || !validTramites.includes(tipoTramite)) {
    return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'tipo_tramite requerido. Valores: ' + validTramites.join(', ') } }];
  }
  return [{ json: {
    user_id: payload.sub,
    tenant_id: payload.tenant_id,
    role: payload.role || 'architect',
    project_id: projectId,
    tipo_tramite: tipoTramite,
    municipio_override: body.municipio || null,
    request_id: 'req_' + Math.random().toString(36).slice(2, 10)
  }}];
} catch (e) {
  return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }];
}

const row = $input.first()?.json;
const sess = $('Decode JWT + Body').first().json;
if (!row || !row.project_id) {
  return [{ json: { _error: 'PROJECT_NOT_FOUND', _status: 404, _details: 'project_id no existe o sin acceso por RLS' } }];
}
if (!row.municipal_template) {
  return [{ json: { _error: 'TEMPLATE_NOT_FOUND', _status: 404, _details: 'No hay plantilla en municipal_templates para municipio=' + (sess.municipio_override || row.project_city) + ' tipo_tramite=' + sess.tipo_tramite + '. Anadirla via INSERT en municipal_templates.' } }];
}
const template = row.municipal_template;
const docsRequired = template.documentos_requeridos || [];

// Mapear que entregables tenemos disponibles
const available = {
  agent_iee: !!row.iee_data,
  agent_rcd: !!row.rcd_data
};

// Para cada doc requerido, verificar disponibilidad
const docsValidados = [];
const docsFaltantes = [];
for (const doc of docsRequired) {
  const responsable = doc.agente_responsable || 'manual';
  const auto_disponible = available[responsable] === true;
  // 'manual' significa que el arquitecto lo aporta a mano - no podemos validar automaticamente
  const isManual = responsable === 'manual';
  if (auto_disponible) {
    docsValidados.push({
      nombre: doc.nombre,
      tipo: doc.tipo,
      origen: 'automatico',
      agente: responsable,
      ref_id: responsable === 'agent_iee' ? row.iee_data.iee_id : (responsable === 'agent_rcd' ? row.rcd_data.rcd_id : null)
    });
  } else if (isManual) {
    docsValidados.push({
      nombre: doc.nombre,
      tipo: doc.tipo,
      origen: 'manual',
      agente: 'manual',
      observacion: 'Aportado manualmente por el tecnico. No se puede validar automaticamente.'
    });
  } else {
    if (doc.obligatorio) {
      docsFaltantes.push({
        nombre: doc.nombre,
        tipo: doc.tipo,
        agente_responsable: responsable,
        criticidad: 'obligatorio',
        accion: 'Ejecutar ' + responsable + ' para este proyecto y aprobar su draft antes de empaquetar el expediente.'
      });
    } else {
      docsValidados.push({
        nombre: doc.nombre,
        tipo: doc.tipo,
        origen: 'opcional',
        agente: responsable,
        observacion: 'Documento opcional no disponible.'
      });
    }
  }
}

const estado = docsFaltantes.length === 0 ? 'listo' : 'incompleto';

return [{ json: {
  ...sess,
  project: {
    id: row.project_id,
    name: row.project_name,
    type: row.project_type,
    city: row.project_city,
    province: row.project_province
  },
  template: {
    id: template.id,
    municipio: template.municipio,
    tipo_tramite: template.tipo_tramite,
    formato_expediente: template.formato_expediente,
    sede_electronica_url: template.sede_electronica_url,
    tamano_maximo_mb: template.tamano_maximo_mb,
    formatos_admitidos: template.formatos_admitidos,
    requiere_firma_digital: template.requiere_firma_digital,
    notas: template.notas,
    citation_source: template.citation_source
  },
  estado,
  documentos_validados: docsValidados,
  documentos_faltantes: docsFaltantes,
  iee_data: row.iee_data,
  rcd_data: row.rcd_data
}}];

const ctx = $input.first().json;

// Estructura ZIP propuesta segun formato_expediente del ayuntamiento
const zipStructure = {};
const sortedDocs = [...ctx.documentos_validados].sort((a, b) => a.nombre.localeCompare(b.nombre));
let idx = 0;
for (const doc of sortedDocs) {
  idx++;
  const slug = doc.nombre.toLowerCase().replace(/[^a-z0-9]+/g, '_').slice(0, 40);
  const filename = `${String(idx).padStart(2, '0')}_${slug}.${doc.tipo.toLowerCase().replace('/', '_')}`;
  zipStructure[filename] = {
    origen: doc.origen,
    agente: doc.agente,
    ref_id: doc.ref_id || null,
    nombre_legal: doc.nombre
  };
}

// Checklist pre-firma para el tecnico
const checklistPreFirma = [
  'Verificar que la documentacion lleva la firma digital del tecnico colegiado',
  'Confirmar que los planos llevan cajetin del estudio con datos del proyecto',
  'Comprobar que el presupuesto desglosado coincide con el del contrato firmado',
  'Validar que las dimensiones (m2, m3) coinciden entre memoria y planos',
  'Pagar las tasas correspondientes antes de presentar (ICIO + tasas urbanisticas)',
  ctx.template.requiere_firma_digital ? 'Firmar digitalmente cada PDF con certificado FNMT/Camerfirma vigente' : 'Imprimir y firmar manualmente cada documento',
  'Subir el ZIP completo a ' + ctx.template.sede_electronica_url
];

const pesoEstimadoMb = Object.keys(zipStructure).length * 1.5;  // ~1.5 MB por PDF tipico

return [{ json: {
  user_id: ctx.user_id,
  tenant_id: ctx.tenant_id,
  project_id: ctx.project.id,
  request_id: ctx.request_id,
  estado: ctx.estado,
  municipio: ctx.template.municipio,
  tipo_tramite: ctx.template.tipo_tramite,
  documentos_validados: ctx.documentos_validados,
  documentos_faltantes: ctx.documentos_faltantes,
  zip_structure: zipStructure,
  zip_filename: `expediente_${ctx.project.id.slice(0, 8)}_${ctx.template.municipio.toLowerCase()}_${ctx.template.tipo_tramite}.zip`,
  peso_estimado_mb: pesoEstimadoMb,
  alertas_formato: pesoEstimadoMb > ctx.template.tamano_maximo_mb ? ['Peso estimado (' + pesoEstimadoMb + ' MB) supera el maximo del ayuntamiento (' + ctx.template.tamano_maximo_mb + ' MB). Comprimir o dividir en envios.'] : [],
  checklist_pre_firma: checklistPreFirma,
  url_sede_electronica: ctx.template.sede_electronica_url,
  citation_source: ctx.template.citation_source,
  notas_municipio: ctx.template.notas,
  iee_disponible: !!ctx.iee_data,
  rcd_disponible: !!ctx.rcd_data
}}];

